#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int blockRow = blockIdx.y * TILE_SIZE;
    int blockCol = blockIdx.x * TILE_SIZE;

    // Each thread computes 4x4 elements of C
    float c[4][4] = {{0.0f}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A
        int A_row = blockRow + ty;
        int A_col = t * TILE_SIZE + tx;
        if (A_row < N && A_col < N) {
            As[ty][tx] = A[A_row * N + A_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B with coalesced access
        int B_row = t * TILE_SIZE + ty;
        int B_col = blockCol + tx;
        if (B_row < N && B_col < N) {
            Bs[ty][tx] = B[B_row * N + B_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sums with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            // Prefetch next values
            float a0 = As[ty][k];
            float a1 = As[ty][k+1];
            float a2 = As[ty][k+2];
            float a3 = As[ty][k+3];

            float b0 = Bs[k][tx];
            float b1 = Bs[k+1][tx];
            float b2 = Bs[k+2][tx];
            float b3 = Bs[k+3][tx];

            // Accumulate results
#pragma unroll
            for (int i = 0; i < 4; i++) {
                c[i][0] += a0 * b0;
                c[i][1] += a0 * b1;
                c[i][2] += a0 * b2;
                c[i][3] += a0 * b3;
                a0 = As[ty][k+i+UNROLL_FACTOR];
            }

            // More accumulation
            c[0][0] += a1 * Bs[k+1][tx];
            c[0][1] += a1 * Bs[k+1][tx+1];
            c[0][2] += a1 * Bs[k+1][tx+2];
            c[0][3] += a1 * Bs[k+1][tx+3];

            c[1][0] += a2 * Bs[k+2][tx];
            c[1][1] += a2 * Bs[k+2][tx+1];
            c[1][2] += a2 * Bs[k+2][tx+2];
            c[1][3] += a2 * Bs[k+2][tx+3];

            c[2][0] += a3 * Bs[k+3][tx];
            c[2][1] += a3 * Bs[k+3][tx+1];
            c[2][2] += a3 * Bs[k+3][tx+2];
            c[2][3] += a3 * Bs[k+3][tx+3];
        }

        __syncthreads();
    }

    // Write results to global memory
